INSERT INTO `announcements` (`id`, `title`, `content`, `category`, `priority`, `is_published`, `expires_at`, `created_by`, `created_at`, `updated_at`) VALUES (1,'End-semester examination schedule released','The end-semester examination timetable for all UG and PG programmes is now available. Examinations begin on the first Monday of December. Hall tickets can be collected from the Examination Cell.','Examinations','important',1,NULL,1,'2026-11-23 06:31:23','2026-11-23 06:31:23');
INSERT INTO `announcements` (`id`, `title`, `content`, `category`, `priority`, `is_published`, `expires_at`, `created_by`, `created_at`, `updated_at`) VALUES (2,'Fee payment deadline for even semester','Students must pay the even-semester fee by 15 January. A late fee of Rs. 100 per day applies after the deadline.','Fees','urgent',1,NULL,1,'2026-11-21 06:31:23','2026-11-21 06:31:23');
INSERT INTO `announcements` (`id`, `title`, `content`, `category`, `priority`, `is_published`, `expires_at`, `created_by`, `created_at`, `updated_at`) VALUES (3,'Annual tech fest registrations open','Registrations for the annual technical festival are open. Events include a hackathon, robotics challenge and paper presentations.','Events','normal',1,NULL,1,'2026-11-19 06:31:23','2026-11-19 06:31:23');
INSERT INTO `announcements` (`id`, `title`, `content`, `category`, `priority`, `is_published`, `expires_at`, `created_by`, `created_at`, `updated_at`) VALUES (4,'Library extended hours during exams','The central library reading hall will remain open 24×7 during the examination period.','Library','normal',1,NULL,1,'2026-11-17 06:31:23','2026-11-17 06:31:23');
INSERT INTO `announcements` (`id`, `title`, `content`, `category`, `priority`, `is_published`, `expires_at`, `created_by`, `created_at`, `updated_at`) VALUES (5,'Campus placement drive – software roles','A placement drive for final-year B.Tech students will be held next week. Register on the placement portal by Friday.','Placements','important',1,NULL,1,'2026-11-15 06:31:23','2026-11-15 06:31:23');
