INSERT INTO `library_resources` (`id`, `title`, `category`, `description`, `location`, `timings`, `url`, `created_at`, `updated_at`) VALUES (1,'Central Library – Regular Timings','Timings','Monday to Saturday: 8:00 AM – 10:00 PM. Sunday: 10:00 AM – 6:00 PM.','Library Block','Mon–Sat 8:00 AM–10:00 PM; Sun 10:00 AM–6:00 PM',NULL,'2026-11-23 06:31:24','2026-11-23 06:31:24');
INSERT INTO `library_resources` (`id`, `title`, `category`, `description`, `location`, `timings`, `url`, `created_at`, `updated_at`) VALUES (2,'Examination Period Timings','Timings','During end-semester examinations the reading hall stays open 24 hours.','Library Block, Reading Hall','24×7 during exams',NULL,'2026-11-23 06:31:24','2026-11-23 06:31:24');
INSERT INTO `library_resources` (`id`, `title`, `category`, `description`, `location`, `timings`, `url`, `created_at`, `updated_at`) VALUES (3,'Book Borrowing Rules','Rule','Undergraduate students may borrow up to 4 books for 14 days. Postgraduate students may borrow up to 6 books for 21 days. A late fee of Rs. 5 per book per day applies.',NULL,NULL,NULL,'2026-11-23 06:31:24','2026-11-23 06:31:24');
INSERT INTO `library_resources` (`id`, `title`, `category`, `description`, `location`, `timings`, `url`, `created_at`, `updated_at`) VALUES (4,'Digital Library & E-Journals','E-Resource','Access to IEEE Xplore, ACM Digital Library, Springer and NPTEL video lectures from the campus network or via remote login.','Library Block, 1st Floor','Mon–Sat 9:00 AM–8:00 PM',NULL,'2026-11-23 06:31:24','2026-11-23 06:31:24');
INSERT INTO `library_resources` (`id`, `title`, `category`, `description`, `location`, `timings`, `url`, `created_at`, `updated_at`) VALUES (5,'Reference & Periodicals Section','Section','Reference books, encyclopaedias, newspapers and over 120 national and international journals.','Library Block, Ground Floor',NULL,NULL,'2026-11-23 06:31:24','2026-11-23 06:31:24');
INSERT INTO `library_resources` (`id`, `title`, `category`, `description`, `location`, `timings`, `url`, `created_at`, `updated_at`) VALUES (6,'Book Bank Scheme','Service','Eligible students may borrow a full semester\'s textbooks through the book bank. Apply at the circulation desk in the first two weeks of the semester.','Circulation Desk',NULL,NULL,'2026-11-23 06:31:24','2026-11-23 06:31:24');
INSERT INTO `medical_facilities` (`id`, `name`, `facility_type`, `description`, `location`, `timings`, `contact_phone`, `doctor_name`, `is_emergency`, `created_at`, `updated_at`) VALUES (1,'Campus Health Centre','Primary Care','General OPD, first aid, basic diagnostics and free consultation for students.','Near Saraswati Hostel','8:00 AM – 8:00 PM (all days)','Ext. 4900','Dr. Neha Kapoor (MBBS)',0,'2026-11-23 06:31:24','2026-11-23 06:31:24');
